function automatic logic[RandWidth-1:0] perm_data (logic [RandWidth-1:0] data,
  rand_perm_t perm_sel);

  for (int k = 0; k < 32; k++) begin : gen_data_loop
    perm_data[k] = data[perm_sel[k]];
